// ─── Produk Komersial — Batch 2 — Produk (SKU) Registry ──────────────────────
// PK-R02B: Produk/SKU individual milik satu Seri, untuk 5 kategori Batch 2
// (Milk Replacer, UMB, Mineral Block, Probiotik, Enzim). Level paling bawah
// dari hierarki Kategori → Brand → Seri → Produk. Setiap produk WAJIB
// memiliki UUID, nama, brand, seri, kategori, kemasan, deskripsi, dan status
// aktif — sesuai kontrak PK-R02B (sama dengan PK-R02A Batch 1).
//
// Data ini diproyeksikan ke PRODUK_KOMERSIAL_LIST generik
// (produkKomersialData.ts) lewat produkKomersialBatch2Adapter.ts agar otomatis
// terhitung pada Ringkasan/Dashboard dan otomatis tersedia untuk dipilih
// Formula lewat readiness layer (formulaProdukKomersialData.ts) — tanpa
// mengubah struktur Formula, Master Pakan, Stok, atau Livestock.

export interface ProdukKomersialBatch2Item {
  uuid: string;
  seriId: string; // UUID → ProdukKomersialBatch2Seri.uuid
  brandId: string; // UUID → ProdukKomersialBatch2Brand.uuid
  kategoriId: string; // UUID → KATEGORI_UUID
  kategoriSlug: string; // routing only
  slug: string;
  namaProduk: string;
  kemasan: string;
  deskripsi: string;
  statusAktif: boolean;
  updatedAt: string;
  // Optional rich fields — PK-R03A.3C/3D
  hargaReferensi?: number;
  hargaPerKg?: number;
}

