/** Daftar produk milik satu seri (UUID). */
export function getBatch2ProdukBySeriId(seriId: string): ProdukKomersialBatch2Item[] {
  return PK_BATCH2_PRODUK_LIST.filter(p => p.seriId === seriId);
}

/** Lookup satu produk via seriId + produkSlug (routing). */
export function getBatch2ProdukBySlug(seriId: string, produkSlug: string): ProdukKomersialBatch2Item | undefined {
  return PK_BATCH2_PRODUK_LIST.find(p => p.seriId === seriId && p.slug === produkSlug);
}

/** Lookup produk via UUID. */
export function getBatch2ProdukByUUID(uuid: string): ProdukKomersialBatch2Item | undefined {
  return PK_BATCH2_PRODUK_LIST.find(p => p.uuid === uuid);
}

/** Jumlah total produk pada satu kategori (slug). */
export function getBatch2JumlahProdukByKategoriSlug(kategoriSlug: string): number {
  return PK_BATCH2_PRODUK_LIST.filter(p => p.kategoriSlug === kategoriSlug).length;
}
